/* Interaktywny artefakt projektowy. Dane demonstracyjne, bez połączenia z API. */
const screens = [
 ['projects','UI-01','Projects'],['overview','UI-02','Project overview'],['staffing','UI-03','Staffing plan'],
 ['resource','UI-04','Position details'],['costs','UI-05','Additional costs'],['cost-detail','UI-06','Cost details'],
 ['tm','UI-07','Time & Material'],['fixed','UI-08','Fixed Price'],['outcome','UI-09','Outcome-based'],['points','UI-10','Story Points'],
 ['compare','UI-11','Scenario comparison'],['sensitivity','UI-12','Sensitivity analysis'],['assumptions','UI-13','Scenario assumptions'],
 ['calendar','UI-14','Working calendars'],['catalog','UI-15','Roles & rates'],['versions','UI-16','Versions & approval'],
 ['report','UI-17','Report preview'],['access','UI-18','Project access'],['states','UI-19','System states'],
 ['create','UI-20','Create project'],['system','UI-21','Design system'],['approved','UI-22','Approved version'],['conflict','UI-23','Save conflict'],['organization','UI-24','Organization defaults']
];
const paths={projects:'M3 5h6l2 2h10v13H3z',overview:'M3 13h7V3H3z M14 21h7V11h-7z M3 21h7v-4H3z M14 7h7V3h-7z',team:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M18 8a3 3 0 0 1 0 6 M22 21v-2a4 4 0 0 0-3-4',chart:'M3 3v18h18 M7 16l5-6 4 2 5-8',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',clock:'M12 8v5l3 2 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',document:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3',plus:'M12 5v14 M5 12h14',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14 M15 15l6 6',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M5 12l4 4L19 6',chevron:'M9 5l7 7-7 7',close:'M6 6l12 12 M18 6L6 18',info:'M12 11v6 M12 7v1 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',copy:'M9 9h12v12H9z M15 9V3H3v12h6',calendar:'M3 5h18v16H3z M7 3v4 M17 3v4 M3 10h18',menu:'M4 6h16 M4 12h16 M4 18h16',edit:'M4 16l12-12 4 4L8 20H4z M14 6l4 4',alert:'M12 3L2 21h20z M12 9v5 M12 17v1',filter:'M3 5h18l-7 8v6l-4 2v-8z',minus:'M5 12h14'};
const ic=(name)=>`<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${paths[name]||paths.document}"/></svg></span>`;
const link=(label,target,cls='btn',icon='')=>`<a class="${cls}" href="#${target}">${icon?ic(icon):''}${label}</a>`;
const btn=(label,action,cls='btn',icon='')=>`<button class="${cls}" data-action="${action}">${icon?ic(icon):''}${label}</button>`;
const badge=(label,type='')=>`<span class="pill ${type}">${label}</span>`;
const escapeHTML=(v)=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n)=>Math.round(n).toLocaleString('en-GB');
const percent=(n)=>n.toFixed(2)+'%';
const months=['Sep 26','Oct 26','Nov 26','Dec 26','Jan 27','Feb 27'];
const hours=[176,176,160,168,152,160];
const positions=[
 {role:'Technical lead',level:'Lead',location:'Poland',count:1,cost:200,sell:320,bill:.9,alloc:[1,1,1,1,1,1]},
 {role:'Backend engineer',level:'Senior',location:'Poland',count:2,cost:160,sell:260,bill:1,alloc:[1,1,1,1,1,1]},
 {role:'QA engineer',level:'Mid',location:'Poland',count:1,cost:120,sell:220,bill:1,alloc:[.5,.75,1,1,1,1]},
 {role:'Product designer',level:'Senior',location:'Poland',count:1,cost:150,sell:250,bill:1,alloc:[.5,.5,.25,.25,0,0]},
 {role:'Project manager',level:'Senior',location:'Poland',count:1,cost:180,sell:280,bill:.5,alloc:[.5,.5,.5,.5,.5,.5]}
];
const extras=[16000,10000,4000,4000,4000,4000];
const monthly=months.map((m,i)=>{const staff=positions.reduce((s,r)=>s+hours[i]*r.alloc[i]*r.count*r.cost,0);const revenue=positions.reduce((s,r)=>s+hours[i]*r.alloc[i]*r.count*r.bill*r.sell,0);return {month:m,staff,extra:extras[i],cost:staff+extras[i],revenue,profit:revenue-staff-extras[i]}});
const totals=monthly.reduce((s,m)=>({revenue:s.revenue+m.revenue,cost:s.cost+m.cost,staff:s.staff+m.staff}),{revenue:0,cost:0,staff:0});
totals.profit=totals.revenue-totals.cost;totals.margin=100*totals.profit/totals.revenue;
const plannedHours=positions.reduce((s,r)=>s+r.alloc.reduce((q,a,i)=>q+a*hours[i]*r.count,0),0);
const billableHours=positions.reduce((s,r)=>s+r.alloc.reduce((q,a,i)=>q+a*hours[i]*r.count*r.bill,0),0);
const ui={scenario:'Base case',filter:'All statuses',sensitivity:{salary:0,rate:0},created:[],selected:'Commerce platform',staffUnit:'FTE',activeCell:0,approved:false};
const field=(label,value,hint='',type='text',origin='')=>`<div class="formfield"><label>${label}<input type="${type}" value="${escapeHTML(value)}" ${type==='number'?'step="any"':''}></label>${hint?`<span class="hint">${hint}</span>`:''}${origin?`<span class="origin">${origin}</span>`:''}</div>`;
const selectField=(label,options,hint='')=>`<div class="formfield"><label>${label}<select>${options.map(x=>`<option>${x}</option>`).join('')}</select></label>${hint?`<span class="hint">${hint}</span>`:''}</div>`;
const table=(headers,rows,cls='')=>`<div class="tablewrap"><table class="${cls}"><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((c,i)=>`<td${i>0&&/^(\d|PLN|−|\+)/.test(c)?' class="num"':''}>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const banner=(title,text,type='',action='')=>`<div class="banner ${type}">${ic(type==='warn'?'alert':'info')}<div><strong>${title}</strong><p>${text}</p></div>${action}</div>`;
const heading=(title,subtitle,actions='')=>`<div class="heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;
const panel=(title,body,subtitle='',action='')=>`<section class="panel"><div class="panelhead"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div><div class="panelbody">${body}</div></section>`;
const stat=(label,value,note,emphasis=false)=>`<div class="metric ${emphasis?'emphasis':''}"><div class="label">${label}</div><div class="value">${value}</div><small>${note}</small></div>`;
const metrics=()=>`<div class="metrics">${stat('Revenue',money(totals.revenue),'PLN · full delivery period')}${stat('Total cost',money(totals.cost),'PLN · including additional costs')}${stat('Project profit',money(totals.profit),'PLN · before tax')}${stat('Project margin',percent(totals.margin),'Target 25.00% · +4.84 pp',true)}</div>`;
const context=()=>`<div class="context"><div class="scenario">${ic('projects')}<label class="muted" for="scenario-select">Scenario</label><select id="scenario-select"><option ${ui.scenario==='Base case'?'selected':''}>Base case</option><option ${ui.scenario==='Lean delivery'?'selected':''}>Lean delivery</option><option ${ui.scenario==='Risk adjusted'?'selected':''}>Risk adjusted</option></select>${badge('Draft')}</div><div class="meta"><span>Sep 2026 – Feb 2027</span><span>PLN</span><span class="desktop">${({fixed:"Fixed Price",outcome:"Outcome-based",points:"Story Points"})[location.hash.slice(1)]||"Time & Material"}</span></div><span class="saved">${ic(location.hash==='#conflict'?'alert':'check')} ${location.hash==='#conflict'?'Not saved':'Saved in demo'}</span></div>`;
const tabs=(active)=>`<nav class="tabs" aria-label="Project sections">${[['overview','Overview'],['staffing','Staffing'],['costs','Additional costs'],['tm','Commercial terms'],['assumptions','Assumptions'],['versions','Versions'],['access','Access']].map(([id,n])=>`<a href="#${id}" class="${active===id?'active':''}">${n}</a>`).join('')}</nav>`;
const projectHeader=(title,sub,active,actions='')=>heading(title,sub,actions)+context()+tabs(active);
const chart=()=>{const max=240000;const y=v=>238-v/max*185;return `<svg class="chart" role="img" aria-label="Monthly revenue and total cost, September 2026 to February 2027, PLN" viewBox="0 0 650 285">${[0,80000,160000,240000].map(v=>`<line class="gridline" x1="55" y1="${y(v)}" x2="630" y2="${y(v)}"/><text x="42" y="${y(v)+4}" text-anchor="end">${v/1000}k</text>`).join('')}${monthly.map((m,i)=>{let x=79+i*92;return `<rect class="revenue" x="${x}" y="${y(m.revenue)}" width="22" height="${238-y(m.revenue)}" rx="3"/><rect class="cost" x="${x+27}" y="${y(m.cost)}" width="22" height="${238-y(m.cost)}" rx="3"/><text x="${x+24}" y="263" text-anchor="middle">${m.month}</text>`}).join('')}</svg>`};
function projectList(){const records=[['Commerce platform','Northstar Retail','Sep 2026 – Feb 2027','Active','3'],['ERP migration','Atlas Manufacturing','Oct 2026 – Jun 2027','Active','2'],['Cloud operations','Vertex Digital','Jan – Dec 2027','Active','1'],['Customer portal','Northstar Retail','Jan – Aug 2026','Archived','2'],...ui.created.map(n=>[n,'New client','To be configured','Active','0'])];return heading('Projects','Plan your team. Understand your project economics.',link('Create project','create','btn brand-action','plus'))+`<div class="toolbar"><div class="left"><div class="search">${ic('search')}<input id="project-search" type="search" placeholder="Search projects or clients" aria-label="Search projects or clients"></div><select id="project-filter" aria-label="Filter project status"><option>All statuses</option><option>Active</option><option>Archived</option></select></div><span class="muted" id="project-count">${records.length} projects</span></div><div class="projectlayout"><section class="panel"><div class="tablewrap"><table><thead><tr><th scope="col">Project / client</th><th scope="col">Delivery period</th><th scope="col">Status</th><th scope="col">Scenarios</th><th scope="col">Actions</th></tr></thead><tbody id="project-rows">${records.map((r,i)=>`<tr class="${i===0?'selected':''}" data-status="${r[3]}" data-search="${escapeHTML(r[0]+' '+r[1])}"><td><button class="link" data-project="${escapeHTML(r[0])}">${escapeHTML(r[0])}</button><small>${r[1]}</small></td><td>${r[2]}</td><td>${badge(r[3],r[3]==='Active'?'blue':'')}</td><td>${r[4]} scenarios</td><td>${btn('•••','project-menu-'+i,'btn small')}</td></tr>`).join('')}</tbody></table></div><div class="tablefoot"><span>Archived projects remain visible</span><span>Reporting currency: PLN</span></div></section><aside class="panel" id="project-sidebar">${scenarioSidebar('Commerce platform')}</aside></div><div class="space"></div>${banner('A clear starting point','Select a project to explore its scenarios, or create a project and build your first staffing plan.')}`}
function scenarioSidebar(name){let base=name==='Commerce platform';return `<div class="panelhead"><div><h2>${escapeHTML(name)}</h2><p>Calculation scenarios</p></div></div>${base?`<div class="scenario-card chosen">${badge('Draft')}<h3>Base case</h3><p>Time & Material · 6 months</p><div class="row"><span>Target margin</span><strong>25.00%</strong></div><p>All required assumptions provided</p>${link('Open scenario','overview','btn primary','arrow')}</div><div class="scenario-card">${badge('Draft')}<h3>Lean delivery</h3><p>Alternative staffing mix</p>${link('Compare with base case','compare','btn small')}</div><div class="scenario-card">${badge('Draft')}<h3>Risk adjusted</h3><p>Higher cost and lower billing</p>${link('View comparison','compare','btn small')}</div>`:`<div class="scenario-card"><h3>Selected project</h3><p>The detailed walkthrough uses Commerce platform sample data.</p>${link('Open sample walkthrough','overview','btn primary')}</div>`}<div class="panelbody">${btn('Add scenario','add-scenario','btn','plus')}</div>`}
function overview(approved=false){return heading('Commerce platform','Northstar Retail / Project economics',link('Compare scenarios','compare','btn','chart')+link('Export report','report','btn primary','download'))+(approved?`<div class="context"><div class="scenario">${ic('lock')}<strong>Base case / Version ${ui.approved?3:2}</strong>${badge('Approved','blue')}</div><span class="meta">Approved ${ui.approved?19:18} Sep 2026 · Read only</span></div>`:context())+tabs('overview')+(approved?banner('This version is approved','Rates, calendars and calculation rules are preserved. Create a draft copy to make changes.','',btn('Create draft copy','duplicate','btn small','copy')):'')+metrics()+`<div class="grid2"><div class="stack">${panel('Project economics',`<div class="legend"><span><i class="dot"></i>Revenue</span><span><i class="dot cost"></i>Total cost</span></div>${chart()}<p class="chartcaption">PLN · costs include personnel, equipment, licenses, cloud and travel</p>`,'Monthly forecast',link('View report','report','btn small quiet'))}${panel(approved?'Preserved assumptions':'Your next decisions',`<ul class="checklist"><li>${ic('check')} Staffing plan complete <span class="end">5 positions / 6 people</span></li><li>${ic('check')} Commercial terms defined <span class="end">Time & Material</span></li><li>${ic('check')} Additional costs included <span class="end">PLN 42,000</span></li><li>${ic('document')} ${approved?'Calculation inputs preserved in this version':'Review assumptions before approval'} ${link(approved?'History':'Review','versions','btn small quiet')}</li></ul>`)}</div><div class="stack">${panel('Cost composition',`<div class="breakdown"><div class="row"><span>Personnel</span><strong>PLN ${money(totals.staff)}</strong></div><div class="bar"><i style="width:94.68%"></i></div></div><div class="breakdown"><div class="row"><span>Additional costs</span><strong>PLN 42,000</strong></div><div class="bar"><i style="width:5.32%;background:var(--teal)"></i></div></div><div class="formula">Cost coverage<strong class="result" style="display:block">100% configured</strong><small>No missing rates or exchange rates</small></div>`,'Full delivery period')}${panel('Team at a glance',`<div class="breakdown"><div class="row"><span>Planned effort</span><strong>${money(plannedHours)} h</strong></div></div><div class="breakdown"><div class="row"><span>Billable effort</span><strong>${billableHours.toLocaleString('en-GB')} h</strong></div></div><div class="breakdown"><div class="row"><span>Average allocation</span><strong>${(plannedHours/992).toFixed(2)} FTE</strong></div></div>${link('Open staffing plan','staffing','btn quiet','team')}`)}</div></div>`}
function staffing(drawer=false){return projectHeader('Staffing plan','Build the team and see the financial impact of each position.','staffing',btn('Add position','add-position','btn primary','plus'))+`<div class="toolbar"><div class="left"><div class="segmented" aria-label="Allocation units">${['FTE','Hours'].map(x=>`<button data-unit="${x}" class="${ui.staffUnit===x?'active':''}">${x}</button>`).join('')}</div><span class="muted">Allocation per person · monthly</span></div><div class="legend"><span>${ic('calendar')}Poland / 8-hour day</span><span>6 people · 5 positions</span></div></div><div class="panel"><div class="tablewrap"><table class="staffing"><thead><tr><th scope="col">Role / seniority</th><th scope="col" class="num">People</th><th scope="col" class="num">Billable</th>${months.map(m=>`<th scope="col" class="num">${m}</th>`).join('')}<th scope="col" class="num">Cost / PLN</th><th scope="col" class="num">Revenue / PLN</th></tr></thead><tbody>${positions.map((r,k)=>`<tr><td><a class="tablelink" href="#resource">${r.role}</a><small>${r.level} · ${r.location}</small></td><td class="num">${r.count}</td><td class="num">${r.bill*100}%</td>${r.alloc.map((a,i)=>`<td><button class="allocation ${a<.5?'low':''}" data-cell="${k}:${i}" aria-label="Edit ${r.role}, ${months[i]}, ${a} FTE per person">${ui.staffUnit==='FTE'?a.toFixed(2):money(a*hours[i])}</button></td>`).join('')}<td class="num total">${money(r.alloc.reduce((s,a,i)=>s+a*hours[i]*r.count*r.cost,0))}</td><td class="num">${money(r.alloc.reduce((s,a,i)=>s+a*hours[i]*r.count*r.sell*r.bill,0))}</td></tr>`).join('')}</tbody><tfoot><tr><td>Total team allocation</td><td class="num">6</td><td></td>${months.map((m,i)=>`<td class="num">${ui.staffUnit==='FTE'?positions.reduce((s,r)=>s+r.count*r.alloc[i],0).toFixed(2):money(positions.reduce((s,r)=>s+r.count*r.alloc[i]*hours[i],0))}</td>`).join('')}<td class="num">${money(totals.staff)}</td><td class="num">${money(totals.revenue)}</td></tr></tfoot></table></div><div class="panelfoot"><span>FTE uses each month's working calendar. Billable share is applied separately.</span><span>PLN</span></div></div><div class="space"></div><div class="grid2 equal">${panel('Allocation over time',`<svg class="chart" role="img" aria-label="Team allocation from 4.50 to 4.75 FTE" viewBox="0 0 620 170">${months.map((m,i)=>{let f=positions.reduce((s,r)=>s+r.count*r.alloc[i],0);return `<rect x="${36+i*97}" y="${130-f*20}" height="${f*20}" width="58" rx="3" fill="var(--blue)"/><text x="${65+i*97}" y="${120-f*20}" text-anchor="middle">${f.toFixed(2)}</text><text x="${65+i*97}" y="153" text-anchor="middle">${m}</text>`}).join('')}</svg>`,'Headcount is weighted by allocation')}${panel('Cost and billing rules',`<ul class="checklist"><li>${ic('info')} Allocation is per person, not per row.</li><li>${ic('info')} Non-billable time still generates cost.</li><li>${ic('info')} ${link('Review calendars and absences','calendar','tablelink')}</li><li>${ic('info')} ${link('Inspect role rates and effective dates','catalog','tablelink')}</li></ul>`)}</div>`+(drawer?resourceDrawer():'')}
function resourceDrawer(){const r=positions[ui.activeCell]||positions[0];return `<div class="drawerscrim"></div><aside class="drawer" aria-label="Position details"><div class="dialoghead"><div><small>Position details</small><h2>${r.role}</h2></div>${link('Close','staffing','btn small','close')}</div><div class="dialogbody"><div class="formgrid">${selectField('Role',[r.role,'Frontend engineer','Business analyst'])}${selectField('Seniority',[r.level,'Mid','Junior'])}${selectField('Location',['Poland','United Kingdom'])}${selectField('Engagement',['Contractor','Employee'])}${field('Headcount',r.count,'Allocation is per person','number')}${field('Billable share (%)',r.bill*100,'Applied to planned hours','number')}${field('Start date','2026-09-01','','date')}${field('End date','2027-02-28','','date')}${field('Cost rate / PLN per hour',r.cost,'Fully loaded hourly cost','number','From organization catalog')}${field('Selling rate / PLN per hour',r.sell,'Subject to commercial terms','number','Scenario override')}</div><div class="summary"><div>Personnel cost<strong>PLN ${money(r.alloc.reduce((s,a,i)=>s+a*hours[i]*r.count*r.cost,0))}</strong></div><div class="right">Billable share<strong>${r.bill*100}%</strong></div></div>${banner('Anonymous role','Assigning a named employee is optional. Plan capacity before selecting a person.')}<h3>Position-specific costs</h3><p style="font-size:12px;margin-top:7px">Add recruitment, equipment or training once. Position costs also appear in Additional costs.</p>${link('Review costs','costs','btn quiet','arrow')}</div><div class="dialogfoot">${link('Cancel','staffing','btn')}${btn('Preview changes','save-resource','btn primary')}</div></aside>`}
function costs(drawer=false){return projectHeader('Additional costs','Every extra expense, with its timing and calculation basis.','costs',link('Add cost','cost-detail','btn primary','plus'))+`<div class="metrics">${stat('Additional costs','42,000','PLN · full delivery period')}${stat('One-off','18,000','Equipment and travel')}${stat('Recurring','24,000','Cloud and licenses')}${stat('Share of total cost','5.32%','Included in project margin',true)}</div><section class="panel"><div class="panelhead"><h2>Cost register</h2><div class="actions">${badge('All scopes','blue')}${badge('All categories')}</div></div>${table(['Category / description','Assigned to','Calculation basis','Period','Total / PLN'],[[`<a class="tablelink" href="#cost-detail">Equipment</a><small>Laptops and peripherals</small>`,'Project','One-off · 12,000','Sep 2026','12,000'],['<strong>Cloud services</strong><small>Development and staging</small>','Project','Monthly · 3,000','Sep 2026 – Feb 2027','18,000'],['<strong>Licenses</strong><small>Delivery tools</small>','Project','Monthly · 1,000','Sep 2026 – Feb 2027','6,000'],['<strong>Travel</strong><small>Client workshop</small>','Discovery','One-off · 6,000','Oct 2026','6,000']])}<div class="panelfoot"><span>No recharged expenses in this scenario</span><strong>Total PLN 42,000</strong></div></section><div class="space"></div><div class="grid2 equal">${panel('Cost schedule',table(['Period','One-off / PLN','Recurring / PLN','Total / PLN'],months.map((m,i)=>[m,money(i===0?12000:i===1?6000:0),money(4000),money(extras[i])])),'Amounts are included once per applicable period')}${panel('Keep your costs explainable',`<ul class="checklist"><li>${ic('check')} No duplicated cost entries</li><li>${ic('check')} All costs have an applicable period</li><li>${ic('check')} All amounts use PLN</li><li>${ic('info')} Personnel overhead is part of the hourly rate</li></ul><div class="formula">Risk reserves are configured separately.<br>${link('Open sensitivity analysis','sensitivity','tablelink')}</div>`)}</div>`+(drawer?costDrawer():'')}
function costDrawer(){return `<div class="drawerscrim"></div><aside class="drawer" aria-label="Cost details"><div class="dialoghead"><div><small>Additional costs</small><h2>Equipment</h2></div>${link('Close','costs','btn small','close')}</div><div class="dialogbody"><div class="formgrid">${selectField('Category',['Equipment','Recruitment','Training','Other'])}${selectField('Scope',['Project','Phase','Staffing position'])}<div class="formfield full"><label>Description<input value="Laptops and peripherals"></label></div>${selectField('Frequency',['One-off','Monthly'])}${selectField('Calculation basis',['Fixed amount','Per person','Per FTE','Percentage'])}${field('Amount',12000,'','number')}${selectField('Currency',['PLN','EUR','USD'])}${field('Applicable date','2026-09-01','','date')}${selectField('Charged to',['Supplier','Client recharge'])}</div><div class="summary"><div>Total expense<strong>PLN 12,000</strong></div><div class="right">Occurrences<strong>1</strong></div></div>${banner('Counted once','This item is already included in the project cost register. It is not an additional copy.')}</div><div class="dialogfoot">${link('Cancel','costs','btn')}${btn('Preview changes','save-cost','btn primary')}</div></aside>`}
const modelMeta={tm:['Time & Material','Billable time × rate'],fixed:['Fixed Price','Agreed scope and price'],outcome:['Outcome-based','Payment for results'],points:['Story Points','Accepted points × price']};
function commercial(model){let body='';if(model==='tm'){body=`<div class="formsection"><h3>Billing rules</h3><div class="formgrid">${selectField('Billing unit',['Hour','Day'])}${field('Hours per billable day',8,'Used only for daily rates','number')}${field('Revenue cap / PLN','1200000','Cap applies to the full term','number')}${selectField('When cap is reached',['Stop billing at cap','Require approved change'])}</div></div><div class="formsection"><h3>Selling rates</h3>${table(['Role','PLN / hour','Billable share'],positions.map(r=>[r.role,money(r.sell),r.bill*100+'%']))}</div>`}if(model==='fixed'){body=`<div class="formsection"><h3>Scope and contract value</h3><div class="formgrid">${field('Agreed price / PLN','1150000','','number')}${selectField('Revenue allocation',['By milestones','Monthly schedule'])}<div class="formfield full"><label>Scope<textarea>Commerce platform redesign: discovery, implementation and launch. Scope changes require an approved change request.</textarea></label></div></div></div><div class="formsection"><h3>Milestones</h3>${table(['Milestone','Acceptance','Revenue / PLN'],[['Discovery','Signed solution scope · Sep','230,000'],['Build','Accepted release · Dec','690,000'],['Launch','Production acceptance · Feb','230,000']])}</div>`}if(model==='outcome'){body=`<div class="formsection"><h3>Outcome definition</h3><div class="formgrid"><div class="formfield full"><label>Measure<input value="Relative improvement in checkout conversion"></label></div>${field('Baseline conversion (%)',2,'Baseline: August 2026','number')}${field('Target conversion (%)',2.4,'20% relative improvement','number')}${selectField('Evidence source',['Client analytics report'])}${field('Measurement end','2027-02-28','','date')}</div></div><div class="formsection"><h3>Compensation</h3><div class="formgrid">${field('Guaranteed fee / PLN',900000,'','number')}${field('Bonus at target / PLN',300000,'All-or-nothing in this example','number')}${field('Maximum fee / PLN',1200000,'','number')}${selectField('Outcome acceptance',['Client confirms results'])}</div></div>`}if(model==='points'){body=`<div class="formsection"><h3>Story Points agreement</h3><div class="formgrid">${selectField('Pricing basis',['Per accepted point'])}${field('Price per point / PLN',4000,'','number')}${field('Sprint length / weeks',2,'','number')}${field('Planned sprints',12,'','number')}${field('Forecast velocity / points',25,'Specific to this team','number')}${field('Expected acceptance (%)',90,'Forecast assumption','number')}</div></div><div class="formsection"><h3>Billing conditions</h3><div class="formgrid">${selectField('Points become billable when',['Accepted by client'])}${selectField('Unfinished work',['Carry over; bill once accepted'])}${selectField('Rework',['Included; do not bill twice'])}${selectField('Estimate changes',['Require agreed revision'])}</div></div>`}
let revenue=model==='tm'?totals.revenue:model==='fixed'?1150000:model==='outcome'?1080000:1080000;return projectHeader('Commercial terms','Define what generates revenue independently from delivery costs.','tm',btn('Preview terms','preview-terms','btn primary','check'))+`<div class="modeltiles">${Object.entries(modelMeta).map(([k,v])=>`<a href="#${k}" class="modeltile ${k===model?'active':''}">${v[0]}<small>${v[1]}</small></a>`).join('')}</div>`+(model==='points'?banner('Pricing assumption to confirm','This proposal uses payment per accepted point. A fixed sprint fee needs a separate business decision.'):model==='outcome'?banner('Forecast is not guaranteed','The expected fee below assumes a 60% chance of achieving the target. Guaranteed and conditional amounts remain separate.'):'')+`<div class="grid2"><section class="panel"><div class="panelhead"><div><h2>${modelMeta[model][0]}</h2><p>Whole project · PLN · Sep 2026 – Feb 2027</p></div>${badge('Draft')}</div>${body}</section><div class="stack">${panel('Revenue preview',`<div class="formula" style="margin-top:0">${model==='tm'?'Billable hours × role selling rates':model==='fixed'?'Agreed price + approved changes':model==='outcome'?'900,000 + 60% × 300,000':'12 × 25 × 90% × PLN 4,000'}<div class="result">PLN ${money(revenue)}</div><small>${model==='outcome'?'Expected revenue':'Forecast revenue'}</small></div><div class="breakdown"><div class="row"><span>Delivery cost</span><strong>PLN ${money(totals.cost)}</strong></div></div><div class="breakdown"><div class="row"><span>Forecast profit</span><strong>PLN ${money(revenue-totals.cost)}</strong></div></div><div class="breakdown"><div class="row"><span>Forecast margin</span><strong>${percent(100*(revenue-totals.cost)/revenue)}</strong></div></div>${model==='outcome'?`<div class="breakdown"><div class="row"><span>Guaranteed fee</span><strong>PLN 900,000</strong></div><div class="row"><span>Fee at target</span><strong>PLN 1,200,000</strong></div></div>`:''}`)}${panel('Scope and safeguards',`<ul class="checklist"><li>${ic('check')} Applies to whole project</li><li>${ic('check')} No overlapping pricing rules</li><li>${ic('check')} Delivery costs unchanged</li><li>${ic('info')} Payment dates do not change margin</li></ul><div class="space"></div>${btn('Configure mixed pricing','mixed-pricing','btn small','plus')}`)}</div></div>`}
function compare(){const lean={revenue:totals.revenue,cost:totals.cost-40000};const risk={revenue:Math.round(totals.revenue*.95),cost:Math.round(totals.staff*1.1)+42000};return heading('Compare scenarios','Commerce platform / Same delivery period and reporting currency',link('Sensitivity analysis','sensitivity','btn primary','chart'))+`<div class="toolbar"><div class="left">${badge('Base case is the reference','blue')}<span class="muted">Sep 2026 – Feb 2027 · PLN</span></div>${btn('Choose scenarios','choose-scenarios','btn','plus')}</div><section class="panel"><div class="tablewrap"><table class="compare"><thead><tr><th scope="col">Metric</th><th scope="col">Base case<br><small>Reference</small></th><th scope="col">Lean delivery<br><small>Cost reduction</small></th><th scope="col">Risk adjusted<br><small>Downside</small></th></tr></thead><tbody><tr><td>Project margin</td>${[totals,lean,risk].map(o=>`<td><span class="big">${percent((o.revenue-o.cost)/o.revenue*100)}</span></td>`).join('')}</tr>${[['Revenue',[totals.revenue,lean.revenue,risk.revenue]],['Total cost',[totals.cost,lean.cost,risk.cost]],['Profit',[totals.profit,lean.revenue-lean.cost,risk.revenue-risk.cost]]].map(([n,arr])=>`<tr><td>${n} / PLN</td>${arr.map(v=>`<td>${money(v)}</td>`).join('')}</tr>`).join('')}<tr><td>Profit vs. reference / PLN</td><td>—</td><td class="positive">+40,000</td><td class="negative">−${money(totals.profit-(risk.revenue-risk.cost))}</td></tr><tr><td>Target margin</td><td>25.00%</td><td>25.00%</td><td>25.00%</td></tr><tr><td>Target assessment</td><td>${badge('Above target','blue')}</td><td>${badge('Above target','blue')}</td><td>${badge('Below target','warn')}</td></tr><tr><td>Changed assumptions</td><td>Current staffing and billing</td><td>Personnel cost −40,000 PLN</td><td>Personnel +10%; revenue −5%</td></tr><tr><td>Calculation status</td><td>${badge('Draft')}</td><td>${badge('Draft')}</td><td>${badge('Draft')}</td></tr></tbody></table></div></section><div class="space"></div><div class="grid2 equal">${panel('Profit comparison',`<svg viewBox="0 0 600 210" class="chart" role="img" aria-label="Scenario profit comparison in PLN">${[[totals.profit,'Base case','var(--blue)'],[lean.revenue-lean.cost,'Lean delivery','var(--teal)'],[risk.revenue-risk.cost,'Risk adjusted','var(--purple)']].map(([v,n,c],i)=>`<text x="0" y="${40+i*65}">${n}</text><rect x="125" y="${24+i*65}" width="${v/1100}" height="26" rx="3" fill="${c}"/><text x="${135+v/1100}" y="${41+i*65}">${money(v)}</text>`).join('')}</svg>`)}${panel('What drives the difference?',`<ul class="checklist"><li>${ic('info')} Lean delivery saves PLN 40,000 in personnel costs.</li><li>${ic('alert')} Risk adjusted falls below the 25% margin target.</li><li>${ic('check')} Additional costs are PLN 42,000 in every scenario.</li><li>${ic('info')} No scenario has been approved.</li></ul>`)}</div>`}
function sensitivity(){return heading('Sensitivity analysis','Explore how cost and selling-rate changes affect the base case.',link('Back to comparison','compare','btn','arrow'))+`<div class="sensitivity"><section class="panel"><div class="panelhead"><h2>Change assumptions</h2></div><div class="panelbody"><div class="sliderfield"><div class="row"><label for="salary-slider">Personnel cost change</label><output id="salary-output">0%</output></div><input id="salary-slider" type="range" min="0" max="20" step="1" value="${ui.sensitivity.salary}"><div class="range-labels"><span>0%</span><span>+20%</span></div></div><div class="sliderfield"><div class="row"><label for="rate-slider">Selling-rate change</label><output id="rate-output">0%</output></div><input id="rate-slider" type="range" min="-15" max="15" step="1" value="${ui.sensitivity.rate}"><div class="range-labels"><span>−15%</span><span>+15%</span></div></div><div class="space"></div><p style="font-size:12px">Additional costs and staffing hours stay at the base-case values.</p><div class="space"></div>${btn('Reset assumptions','reset-sensitivity','btn small')}${btn('Save as scenario','save-sensitivity','btn primary small')}</div></section><div class="stack"><div class="metrics" style="grid-template-columns:repeat(2,1fr);margin:0">${stat('Simulated profit','<span id="sim-profit"></span>','PLN · all included costs')}${stat('Simulated margin','<span id="sim-margin"></span>','Compared with 25% target',true)}</div>${panel('Margin sensitivity',`<div class="tablewrap"><table class="heatmap"><thead><tr><th>Cost change ↓ / Rate change →</th>${[-10,-5,0,5,10].map(x=>`<th>${x>0?'+':''}${x}%</th>`).join('')}</tr></thead><tbody>${[0,5,10,15,20].map(c=>`<tr><th>+${c}%</th>${[-10,-5,0,5,10].map(r=>{const rev=totals.revenue*(1+r/100),cost=totals.staff*(1+c/100)+42000;const m=(rev-cost)/rev*100;return `<td class="${m<20?'heat1':m<25?'heat2':m<30?'heat3':'heat4'} ${c===0&&r===0?'reference':''}">${m.toFixed(1)}%</td>`}).join('')}</tr>`).join('')}</tbody></table></div><p class="chartcaption">Outlined cell: base case. Values are project margin, not markup.</p>`,'Same team, billable hours and additional costs')}${banner('Temporary simulation','Changing the sliders does not modify the base-case scenario. Save a separate scenario to retain a variation.')}</div></div>`}
function assumptions(){return projectHeader('Scenario assumptions','Understand inherited values and make deliberate overrides.','assumptions',btn('Preview assumptions','preview-assumptions','btn primary','check'))+`<div class="grid2"><section class="panel"><div class="formsection"><h3>Period and reporting</h3><div class="formgrid">${field('Start date','2026-09-01','','date','Inherited from project')}${field('End date','2027-02-28','','date','Inherited from project')}${selectField('Reporting currency',['PLN','EUR','USD'])}${field('Target margin (%)',25,'Profit ÷ revenue','number','Scenario override')}</div></div><div class="formsection"><h3>Working time</h3><div class="formgrid">${selectField('Working calendar',['Poland / 2026–2027'])}${field('Hours per working day',8,'','number','Organization default (copied)')}${selectField('Paid leave cost',['Cost continues; no revenue'])}${field('Planned leave / days',0,'Per-person exceptions in calendar','number')}</div></div><div class="formsection"><h3>Exchange rates</h3>${table(['Pair','Rate','Effective dates','Source'],[['EUR → PLN','4.3000','01 Sep 2026 – 28 Feb 2027','Manual entry'],['USD → PLN','3.9000','01 Sep 2026 – 28 Feb 2027','Organization default']])}<p class="chartcaption">Illustrative planning rates, not current market rates. All base-case entries are in PLN.</p></div></section><div class="stack">${panel('Where values come from',`<ul class="checklist"><li>${ic('settings')} Organization default <span class="end">Copied value</span></li><li>${ic('projects')} Project setting <span class="end">Inherited</span></li><li>${ic('edit')} Scenario override <span class="end">Explicit change</span></li></ul><div class="formula">Updating an organization default does not silently change this calculation.</div>`)}${panel('Rate validation',`<ul class="checklist"><li>${ic('check')} No overlapping effective dates</li><li>${ic('check')} Required currencies covered</li><li>${ic('check')} Sources recorded</li></ul>${link('Review working calendar','calendar','btn quiet','calendar')}`)}</div></div>`}
function calendar(){const days=Array.from({length:42},(_,i)=>{const d=i-3;return d>0&&d<=31?d:0});return heading('Working calendars','Calendars determine available hours and FTE conversion.',btn('Preview calendar','preview-calendar','btn primary','check'))+`<div class="toolbar"><div class="left"><select aria-label="Calendar"><option>Poland / standard workweek</option></select>${badge('Organization default','blue')}</div><span class="muted">8 hours/day · Monday–Friday</span></div><div class="grid2 equal">${panel('January 2027',`<div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="dayname">${d}</div>`).join('')}${days.map((d,i)=>`<div class="day ${i%7>=5?'off':''} ${d===1||d===6?'holiday':''}">${d||''}${d===1?'<small>New Year</small>':d===6?'<small>Epiphany</small>':''}</div>`).join('')}</div><div class="space"></div><div class="legend"><span><i class="dot"></i>Public holiday</span><span>Shaded cells: non-working days</span></div>`)}${panel('Available hours',table(['Month','Working days','Hours / 1 FTE'],months.map((m,i)=>[m,String(hours[i]/8),String(hours[i])]))+`<div class="formula">Full period: <strong>124 working days / 992 hours</strong></div>`,'Before personal absences')}</div><div class="space"></div>${panel('Absence rules',table(['Absence type','Personnel cost','Client billing'],[['Paid leave','Included','Excluded unless contract permits'],['Unpaid leave','Excluded under configured cost rule','Excluded'],['Training','Included','Based on commercial agreement']]),'Explicit rules prevent billable time from being confused with availability')}`}
const catalogDictionaries=[
 {key:'roles',title:'Roles',column:'Role',items:['Backend engineer','Data engineer','Product designer','Project manager','QA engineer','Technical lead']},
 {key:'seniorities',title:'Seniorities',column:'Seniority',items:['Junior','Mid','Senior','Lead','Principal']},
 {key:'locations',title:'Locations',column:'Location',items:['Poland','Portugal','Spain','United Kingdom','United States']},
 {key:'engagement-types',title:'Engagement types',column:'Engagement type',items:['Contractor','Internal','Partner']},
 {key:'vendors',title:'Vendors',column:'Vendor',items:['Acme Technology','Northstar Talent','Internal']}
];
function dictionaryCard(d,focused=false){return `<section class="panel catalog-dictionary ${focused?'catalog-dictionary--focus':''}" data-catalog-dimension="${d.key}"><div class="panelhead"><h2>${d.title}</h2>${btn('Add '+d.column.toLowerCase(),'add-dimension-'+d.key,'btn small primary','plus')}</div><div class="catalog-entries">${d.items.map(name=>`<div class="catalog-entry"><span>${escapeHTML(name)}</span>${btn('Rename','rename-'+d.key+'-'+escapeHTML(name),'btn small quiet','edit')}</div>`).join('')}</div>${focused?`<div class="dimension-form"><h3>Add an entry to the ${d.title.toLowerCase()} dictionary</h3><div class="formfield"><label>${d.column} name<input type="text" placeholder="Enter ${d.column.toLowerCase()} name"></label></div><div class="actions">${btn('Cancel','cancel-dimension','btn small')}${btn('Save new entry','save-dimension','btn small primary')}</div></div>`:''}</section>`}
function catalog(){const rateRows=positions.map((r,i)=>[r.role,r.level,'Poland',i===2?'Internal':'Contractor',i===2?'Internal':'Acme Technology','01 Sep 2026 – 28 Feb 2027',`${r.sell} PLN / hour`,i===1?badge('Restricted','warn'):`${r.cost} PLN / hour`,btn('Edit','edit-rate-'+i,'btn small quiet','edit')]);return heading('Roles & rates','Manage default hourly rates and the shared dictionaries used across staffing plans.')+`<div class="catalog-section-head"><div><h2>Default rates</h2><p>Rates are matched by role, seniority, location, engagement type and vendor.</p></div>${btn('Add default rate','add-rate','btn primary','plus')}</div><section class="panel catalog-rate-panel"><p class="catalog-count">Showing 5 default rates</p>${table(['Role','Seniority','Location','Engagement type','Vendor','Effective period','Default selling rate','Default cost rate','Actions'],rateRows)}<div class="panelfoot"><span>Cost rates may be restricted by access permissions.</span><span>Amounts and dates are examples.</span></div></section><div class="catalog-section-head catalog-dictionary-title"><div><h2>Dimensions</h2><p>Shared name dictionaries used to configure staffing and default rates.</p></div></div><div class="catalog-dictionaries">${catalogDictionaries.map(d=>dictionaryCard(d)).join('')}</div><p class="catalog-demo-note">Design reference only · Sample values · Editing is shown as a visual prototype and is not connected to the application API.</p>`}
function versions(){return projectHeader('Versions & approval','Review assumptions, preserve a version and retain its calculation inputs.','versions',link('Preview report','report','btn','document'))+`<div class="grid2"><section class="panel"><div class="panelhead"><h2>Version history</h2></div><div class="panelbody"><div class="version"><div class="vicon">${ic('edit')}</div><div><h3>Version 3 / Current draft</h3><p>Updated staffing and additional costs</p><small>19 Sep 2026, 10:42 · Demo author</small></div>${badge('Draft')}</div><div class="version"><div class="vicon">${ic('lock')}</div><div><h3>Version 2 / Approved baseline</h3><p>Saved rates, calendars and calculation rules</p><small>18 Sep 2026, 16:10 · Demo approver</small></div>${link('Open','approved','btn small')}</div><div class="version"><div class="vicon">${ic('copy')}</div><div><h3>Version 1 / Initial estimate</h3><p>Original planning assumptions</p><small>17 Sep 2026, 09:00 · Demo author</small></div>${badge('Draft')}</div></div><div class="panelfoot"><span>Illustrative history for design review</span><span>3 versions</span></div></section>${panel('Approve this calculation',`<ul class="checklist"><li>${ic('check')} Required inputs complete</li><li>${ic('check')} No missing rates or calendars</li><li>${ic('check')} All changes saved</li><li>${ic('check')} Margin above target</li></ul><label class="checkrow"><input id="approve-check" type="checkbox">I have reviewed the assumptions and understand that this version will be read only.</label>${btn('Approve version','approve','btn primary','lock')}<p style="font-size:11px;margin-top:12px">Approval is a deliberate human action. Later changes require a draft copy.</p>`)}</div><div class="space"></div>${panel('Change details',table(['When','Who','Change','Previous','Current'],[['19 Sep, 10:42','Demo author','Travel / one-off','PLN 5,000','PLN 6,000'],['19 Sep, 10:15','Demo author','QA allocation / Oct','0.50 FTE','0.75 FTE'],['19 Sep, 09:30','Demo author','Target margin','20.00%','25.00%']]))}`}
function report(){return heading('Report preview','A concise financial summary for a decision-making conversation.',btn('Print / Save as PDF','print','btn primary','download')+btn('Export demo data','export','btn','download'))+`<article class="report"><div class="reportbrand"><span>Staffing planner / Project economics</span><span>19 September 2026</span></div>${badge('Draft · illustrative data')}<h2>Commerce platform</h2><p>Northstar Retail · Base case · Version 3</p><p style="margin-top:6px">01 September 2026 – 28 February 2027 · Time & Material · PLN</p>${metrics()}<h3>Revenue and cost profile</h3><div class="legend" style="margin-top:12px"><span><i class="dot"></i>Revenue</span><span><i class="dot cost"></i>Total cost</span></div>${chart()}<div class="grid2 equal"><div><h3>Planning assumptions</h3><ul class="checklist"><li>5 staffing positions / 6 people</li><li>Poland calendar / 8-hour day</li><li>PLN 42,000 additional costs</li><li>25.00% target margin</li></ul></div><div><h3>Decision summary</h3><p style="margin-top:12px">The base case delivers a ${percent(totals.margin)} margin, 4.84 percentage points above the target.</p><p style="margin-top:12px">The downside scenario falls below target. Review cost increases and selling-rate changes before committing.</p></div></div><div class="reportfooter"><span>Draft forecast · not actual delivery results</span><span>Confidential · 1</span></div></article>`}
function access(){return projectHeader('Project access','Control project actions and visibility of personnel costs.','access',btn('Review access changes','access-review','btn primary','lock'))+banner('Access design proposal','Identity integration and access-grant workflows require implementation and approval. The entries below are sample roles.')+`<section class="panel">${table(['User / role','Project access','Edit calculation','Approve version','Personnel costs'],[['<strong>Demo project manager</strong><small>Calculation author</small>','Assigned','Allowed','Allowed','Restricted'],['<strong>Demo finance partner</strong><small>Calculation author</small>','Assigned','Allowed','Allowed','Allowed'],['<strong>Demo delivery sponsor</strong><small>Read-only viewer</small>','Assigned','Read only','Not allowed','Restricted']])}</section><div class="space"></div><div class="grid2 equal">${panel('Personnel cost visibility',`<p style="font-size:12px">Project personnel costs require both the global permission and cost visibility on this project assignment.</p><div class="space"></div><ul class="checklist"><li>${ic('lock')} Creating a project does not grant cost visibility.</li><li>${ic('lock')} Copying a project does not copy cost grants.</li><li>${ic('lock')} Exports follow the same access rules.</li></ul>`)}${panel('Restricted view',`<div class="formula" style="margin-top:0">Individual cost rate<strong class="result" style="display:block;font-size:19px">Restricted</strong><small>Never displayed as PLN 0 or an empty numeric value</small></div><p style="font-size:12px;margin-top:15px">Aggregate profitability is shown only if the server explicitly authorizes it. It must not expose a restricted person's cost indirectly.</p>`)}</div>`}
function states(){return heading('System states','Interaction patterns for incomplete data, access and save failures.',link('Design system','system','btn'))+`<div class="statesgrid"><section class="state">${ic('projects')}<h2>No projects yet</h2><p>Create a project to start planning your team, rates and delivery costs.</p>${link('Create project','create','btn primary','plus')}</section><section class="state"><h2>Loading projects</h2><div class="skeleton"></div><div class="skeleton short"></div><div class="skeleton"></div><p role="status">Loading your projects…</p></section><section class="state">${ic('alert')}<h2>Calculation incomplete</h2><p>January has no exchange rate for EUR → PLN. Complete the missing rate before reviewing the total.</p>${link('Review exchange rates','assumptions','btn')} ${badge('Result unavailable','warn')}</section><section class="state">${ic('clock')}<h2>Projects could not be loaded</h2><p>The request timed out. No project data has been changed.</p>${btn('Try again','retry','btn primary')}</section><section class="state">${ic('lock')}<h2>Project not found</h2><p>This project is not available. Return to the projects you can access.</p>${link('Back to projects','projects','btn')}</section><section class="state">${ic('edit')}<h2>Your changes were not saved</h2><p>This item changed since you opened it. Keep your input and reload the latest version.</p>${link('Review conflict','conflict','btn primary')}</section><section class="state">${ic('info')}<h2>No revenue in this period</h2><p>Profit: −PLN 12,000. Margin: Not applicable. A zero denominator does not produce 0% margin.</p>${badge('Not applicable')}</section><section class="state">${ic('alert')}<h2>Capacity exceeded</h2><p>QA engineer / October: 184 planned hours exceed 176 available hours. Review allocation or document overtime.</p>${link('Review allocation','staffing','btn')}</section></div>`}
function createProject(){return heading('Create project','Start with project details. Build the first scenario next.',link('Cancel','projects','btn'))+`<div class="stepper"><span class="current"><b>1</b>Project details</span><span><b>2</b>Scenario assumptions</span><span><b>3</b>Staffing and terms</span></div><div class="grid2"><form id="create-project-form" class="panel"><div class="formsection"><h3>Project details</h3><div class="formgrid"><div class="formfield full"><label>Project name<input id="new-project-name" required maxlength="120" placeholder="e.g. Commerce platform"></label></div>${field('Client','Northstar Retail')}${field('Owner','Demo project manager')}${field('Start date','2026-09-01','','date')}${field('End date','2027-02-28','','date')}${selectField('Reporting currency',['PLN','EUR','USD'])}<div class="formfield full"><label>Description<textarea placeholder="Briefly describe the delivery scope"></textarea></label></div></div></div><div class="dialogfoot"><button type="submit" class="btn primary">Create project</button></div></form>${panel('What happens next?',`<ul class="checklist"><li>${ic('settings')} Configure your first scenario</li><li>${ic('team')} Plan roles and allocation</li><li>${ic('document')} Choose commercial terms</li><li>${ic('chart')} Review costs and profitability</li></ul><div class="formula">You can save a draft before all calculation inputs are complete.</div>`)}</div>`}
function designSystem(){return heading('Design system','Brand foundations translated into a focused planning workspace.','<a class="btn primary" href="gallery.html">Open screen gallery</a>')+`<section class="panel"><div class="panelhead"><h2>Color roles</h2></div><div class="panelbody"><div class="tokens">${[['White','var(--paper)','#FFFFFF'],['Light steel','var(--wash)','#F0F2F5'],['Blue','var(--blue)','#0066FF'],['Orange','var(--orange)','#FF5500'],['Steel gray','var(--sc-color-steel-gray-75)','#3B4252'],['Black','var(--ink)','#000000']].map(([n,c,h])=>`<div><div class="swatch" style="background:${c}"></div><strong>${n}</strong><small>${h}</small></div>`).join('')}</div><div class="space"></div><p style="font-size:12px">Orange accents sit on white. Blue supports interaction on light steel. Secondary hues identify chart series only.</p></div></section><div class="space"></div><div class="grid2 equal">${panel('Type and rhythm',`<div class="tokenrow"><span class="muted">28 / 35</span><h1>Project economics</h1></div><div class="tokenrow"><span class="muted">18 / 27</span><h2>Staffing plan</h2></div><div class="tokenrow"><span class="muted">14 / 21</span><span>Manrope. Clear labels. Sentence case.</span></div><div class="tokenrow"><span class="muted">Numbers</span><strong class="num">PLN 1,124,676 · 29.84%</strong></div>`)}${panel('Controls and feedback',`<div class="actions">${btn('Primary action','sample-action','btn primary')}${btn('Secondary','sample-action','btn')}${btn('Text action','sample-action','btn quiet')}</div><div class="space"></div><div class="actions">${badge('Draft')}${badge('Approved','blue')}${badge('Needs attention','warn')}${badge('Archived')}</div><div class="space"></div>${field('Cost rate / PLN per hour','200','Units remain visible while editing')}`)}</div><div class="space"></div>${banner('Design principle','The staffing grid is the primary working surface. Charts explain the consequences; they never replace the underlying calculation.')}`}
function conflict(){return projectHeader('Save conflict','Your input is preserved while you review the latest version.','staffing')+banner('Your changes were not saved','This position changed since you opened it. Reload the latest version before trying again.','warn')+`<div class="grid2 equal">${panel('Your unsaved input',table(['Position','Month','Your allocation'],[['QA engineer','Oct 2026','0.75 FTE']])+`<div class="space"></div><p style="font-size:12px">The server rejected the save. Your value has not replaced the current data.</p>`)}${panel('Next step',`<p style="font-size:12px">Keep a copy of your input, then reload. The conflict response does not identify another editor or reveal their changes.</p><div class="space"></div><div class="actions">${btn('Copy my input','copy-input','btn','copy')}${btn('Reload latest version','reload-latest','btn primary')}</div><div class="formula">After reloading, review and reapply your input deliberately. No automatic overwrite or merge.</div>`)}</div>`}
const renderers={projects:projectList,overview:()=>overview(),staffing:()=>staffing(),resource:()=>staffing(true),costs:()=>costs(),'cost-detail':()=>costs(true),tm:()=>commercial('tm'),fixed:()=>commercial('fixed'),outcome:()=>commercial('outcome'),points:()=>commercial('points'),compare,sensitivity,assumptions,calendar,catalog,versions,report,access,states,create:createProject,system:designSystem,approved:()=>overview(true),conflict,organization};
function render(){const key=location.hash.slice(1)||'projects';const screen=screens.find(s=>s[0]===key)||screens[0];const k=screen[0];const mainNav=[['projects','projects','Projects'],['compare','chart','Compare scenarios'],['catalog','team','Roles & rates'],['calendar','calendar','Working calendars'],['organization','settings','Organization defaults']];const projectKeys=['overview','staffing','resource','costs','cost-detail','tm','fixed','outcome','points','assumptions','versions','access','approved','conflict'];document.title=screen[2]+' — Staffing planner';document.getElementById('app').innerHTML=`<header class="topbar"><a href="#projects" class="brand"><span class="brandmark" aria-hidden="true"><i></i><i></i><i></i></span><span><strong>Staffing planner</strong><small>Project economics</small></span></a><div class="crumb"><a href="#projects">Workspace</a>${ic('chevron')}<span>${projectKeys.includes(k)?'Commerce platform':screen[2]}</span></div><div class="topright">${badge('Internal workspace')}<span class="muted" style="font-size:11px">Project manager</span><div class="avatar" aria-label="Demo project manager">PM</div>${btn('Menu','mobile-menu','btn small onlymobile','menu')}</div></header><div class="layout"><nav class="rail" aria-label="Main navigation">${mainNav.map(([id,icon,label])=>`<a href="#${id}" class="${k===id?'active':''}">${ic(icon)}${label}</a>`).join('')}<div class="section-label">Commerce platform</div>${[['overview','overview','Overview'],['staffing','team','Staffing plan'],['costs','document','Additional costs'],['tm','document','Commercial terms'],['assumptions','settings','Assumptions'],['versions','clock','Versions & approval']].map(([id,icon,label])=>`<a href="#${id}" class="${k===id||(id==='tm'&&['fixed','outcome','points'].includes(k))||(id==='staffing'&&k==='resource')?'active':''}">${ic(icon)}${label}</a>`).join('')}<div class="railbottom"><p>Planning workspace<br>All amounts in scenario currency</p><a href="#access" style="padding:10px 0">${ic('lock')}Project access</a></div></nav><main id="content" tabindex="-1">${renderers[k]()}</main></div><footer class="demofooter"><span>${screen[1]} · Design proposal · Sample data</span><div class="links"><a href="spec/UI_SPEC.md">Specification</a><a href="gallery.html">Screen gallery</a><label for="screen-picker">Screen</label><select id="screen-picker">${screens.map(([id,num,n])=>`<option value="${id}" ${id===k?'selected':''}>${num} / ${n}</option>`).join('')}</select></div></footer>`;bind(k);if(k==='sensitivity')updateSensitivity();}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.className='show';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.className='',4200)}
function modal(title,body,foot=''){const d=document.getElementById('dialog');d.innerHTML=`<div class="dialoghead"><h2 id="dialog-title">${title}</h2><button class="btn small" id="close-dialog" aria-label="Close dialog">${ic('close')}</button></div><div class="dialogbody">${body}</div><div class="dialogfoot">${foot||'<button class="btn primary" id="done-dialog">Done</button>'}</div>`;d.showModal();d.querySelector('#close-dialog').onclick=()=>d.close();const done=d.querySelector('#done-dialog');if(done)done.onclick=()=>d.close();d.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));d.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>d.close()));}
function bind(k){document.getElementById('screen-picker').onchange=e=>location.hash=e.target.value;document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{ui.staffUnit=b.dataset.unit;render()});document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{const [r,m]=b.dataset.cell.split(':').map(Number);ui.activeCell=r;modal('Edit allocation',`<p style="margin-bottom:18px">${positions[r].role} / ${months[m]}</p>${field('Allocation per person / FTE',positions[r].alloc[m],'Available hours: '+hours[m]+' per person','number')}<div class="formula">This design preview keeps the reference calculation fixed. Production edits must recalculate and save through the server.</div>`,`${link('Open position details','resource','btn primary')}`)});document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{document.querySelectorAll('#project-rows tr').forEach(r=>r.classList.remove('selected'));b.closest('tr').classList.add('selected');if(innerWidth<=1150){location.hash='overview';return}document.getElementById('project-sidebar').innerHTML=scenarioSidebar(b.dataset.project);document.querySelectorAll('#project-sidebar [data-action]').forEach(x=>x.onclick=()=>action(x.dataset.action));});let sc=document.getElementById('scenario-select');if(sc)sc.onchange=e=>{ui.scenario=e.target.value;if(ui.scenario!=='Base case'){location.hash='compare';toast('Compare the selected scenario with the base case.')}else render()};if(k==='projects'){const filter=()=>{const q=document.getElementById('project-search').value.toLowerCase();const s=document.getElementById('project-filter').value;let count=0;document.querySelectorAll('#project-rows tr').forEach(r=>{const show=r.dataset.search.toLowerCase().includes(q)&&(s==='All statuses'||r.dataset.status===s);r.hidden=!show;if(show)count++});document.getElementById('project-count').textContent=count+' projects';};document.getElementById('project-search').oninput=filter;document.getElementById('project-filter').onchange=filter;}if(k==='sensitivity'){document.getElementById('salary-slider').oninput=updateSensitivity;document.getElementById('rate-slider').oninput=updateSensitivity;}const form=document.getElementById('create-project-form');if(form)form.onsubmit=e=>{e.preventDefault();const name=document.getElementById('new-project-name').value.trim();if(!name)return;ui.created.push(name);location.hash='projects';toast('Project added to this demo session. Refreshing resets demo data.');};}
function updateSensitivity(){const c=Number(document.getElementById('salary-slider').value),r=Number(document.getElementById('rate-slider').value);ui.sensitivity={salary:c,rate:r};const rev=Math.round(totals.revenue*(100+r)/100),cost=Math.round(totals.staff*(100+c)/100)+42000;document.getElementById('salary-output').textContent='+'+c+'%';document.getElementById('rate-output').textContent=(r>0?'+':'')+r+'%';document.getElementById('sim-profit').textContent=money(rev-cost);document.getElementById('sim-margin').textContent=percent((rev-cost)/rev*100);}
function action(a){if(a==='confirm-approval'){ui.approved=true;document.getElementById('dialog').close();location.hash='approved';return}if(a==='add-position'){modal('Add staffing position',`<div class="formgrid">${selectField('Role',['Backend engineer','QA engineer','Technical lead'])}${selectField('Seniority',['Senior','Mid'])}${field('Headcount',1,'','number')}${field('Allocation / FTE',1,'Per person','number')}</div><div class="formula">Anonymous roles can be planned before people are assigned.</div>`,link('Preview position details','resource','btn primary'));return}if(a==='mobile-menu'){document.querySelector('.layout').classList.toggle('mobile-nav-open');return}if(a==='print'){window.print();return}if(a==='export'){const rows=[['Period','Revenue PLN','Personnel cost PLN','Additional costs PLN','Total cost PLN','Profit PLN'],...monthly.map(m=>[m.month,m.revenue,m.staff,m.extra,m.cost,m.profit])];const url=URL.createObjectURL(new Blob([rows.map(r=>r.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const l=document.createElement('a');l.href=url;l.download='commerce-platform-demo.csv';l.click();URL.revokeObjectURL(url);return}if(a==='reset-sensitivity'){ui.sensitivity={salary:0,rate:0};render();return}if(a==='approve'){if(!document.getElementById('approve-check').checked){toast('Confirm that you reviewed the assumptions before approving.');return}modal('Approve version 3?',`<p>This demonstration opens the read-only design. No server record is changed.</p><div class="formula">Production approval preserves rates, calendars, exchange rates and rule versions. This action cannot be undone.</div>`,btn('Preview approved version','confirm-approval','btn primary','lock'));return}if(a==='duplicate'){ui.scenario='Base case';location.hash='overview';toast('Draft-copy interaction preview. The reference dataset is unchanged.');return}if(a==='copy-input'){navigator.clipboard?.writeText('QA engineer / Oct 2026 / 0.75 FTE').then(()=>toast('Your unsaved input was copied.')).catch(()=>modal('Your unsaved input','<textarea style="width:100%">QA engineer / Oct 2026 / 0.75 FTE</textarea>'));return}if(a==='reload-latest'){location.hash='staffing';toast('Latest reference data loaded in the demo.');return}if(a==='retry'){location.hash='projects';return}if(a.startsWith('project-menu-')){modal('Project actions',`<div class="actions">${link('View sample project','overview','btn','overview')}${btn('Edit details','edit-project','btn','edit')}${btn('Copy project','copy-project','btn','copy')}${btn('Archive project','archive-project','btn')}</div>`);return}if(a==='archive-project'){modal('Archive project?',`<p>Archiving keeps the project and its calculations visible. It does not delete data or freeze draft scenarios.</p><div class="formula">Restoring an archived project is not available in the current scope.</div>`,btn('Preview archive result','archive-confirm','btn primary'));return}if(a==='archive-confirm'){document.getElementById('dialog').close();toast('Archive interaction reviewed. No project was changed.');return}if(a==='edit-project'){modal('Edit project details',`<div class="formgrid">${field('Project name','Commerce platform')}${field('Client','Northstar Retail')}</div><div class="space"></div>${banner('Approved calculation exists','Reporting currency and delivery dates are locked. Descriptive fields remain editable.')}`);return}if(a==='mixed-pricing'){modal('Mixed pricing by scope',table(['Scope','Model','Dates'],[['Discovery','Fixed Price','01–30 Sep 2026'],['Build','Time & Material','01 Oct 2026–28 Feb 2027']])+`<div class="formula">A scope and date range cannot overlap another pricing rule without an explicit combined pricing agreement.</div>`);return}if(a==='add-rate'){modal('Add default rate',`<div class="formgrid">${selectField('Role',['Technical lead','Backend engineer'])}${field('Cost / PLN per hour',200,'','number')}${field('Effective from','2027-03-01','','date')}${field('Effective to','','Leave empty for no expiry','date')}</div>`);return}if(a==='add-scenario'||a==='save-sensitivity'||a==='copy-project'){modal(a==='copy-project'?'Copy project':'Create scenario',`${field('Name',a==='save-sensitivity'?'Sensitivity variation':'New draft')}<div class="formula">This is an interaction preview. Production copies must be independent drafts and must not inherit cost-access grants.</div>`);return}if(a==='choose-scenarios'){modal('Choose scenarios',`<div class="checkrow"><input type="checkbox" checked aria-label="Base case">Base case</div><div class="checkrow"><input type="checkbox" checked aria-label="Lean delivery">Lean delivery</div><div class="checkrow"><input type="checkbox" checked aria-label="Risk adjusted">Risk adjusted</div><p>Comparison uses these three reference scenarios in the prototype.</p>`);return}if(a==='save-resource'||a==='save-cost'||a.startsWith('preview-')||a==='access-review'){modal('Review changes',`<p>The fields demonstrate the proposed editing experience. The reference dataset remains fixed in this design prototype.</p><div class="formula">In the application, the server validates inputs, recalculates results and confirms the save. A conflict must never silently overwrite another user's work.</div>`);return}toast('Component interaction preview. No application data changed.');}
function organization(){return heading('Organization defaults','Reusable settings for new calculations. Existing scenarios keep their saved values.',btn('Preview default changes','preview-defaults','btn primary','check'))+banner('Defaults are copied, not live links','Changing a default affects future use. Existing drafts and approved versions do not update silently.')+`<div class="grid2"><section class="panel"><div class="formsection"><h3>Planning defaults</h3><div class="formgrid">${selectField('Reporting currency',['PLN','EUR','USD'])}${field('Target margin (%)',25,'','number')}${selectField('Working calendar',['Poland / standard workweek'])}${field('Hours per working day',8,'','number')}</div></div><div class="formsection"><h3>Cost categories</h3>${table(['Category','Default basis','Available for'],[['Equipment','One-off amount','Project / position'],['Cloud services','Monthly amount','Project / phase'],['Licenses','Per person / month','Project / position'],['Travel','One-off amount','Project / phase'],['Risk reserve','Percentage of selected costs','Scenario']])}</div><div class="formsection"><h3>Exchange rates</h3>${table(['Pair','Rate','Effective from','Effective to'],[['EUR → PLN','4.3000','01 Sep 2026','28 Feb 2027'],['USD → PLN','3.9000','01 Sep 2026','28 Feb 2027']])}<p class="chartcaption">Manual planning examples. Not a live exchange-rate feed.</p></div></section><div class="stack">${panel('Default libraries',`<ul class="checklist"><li>${ic('team')}${link('Roles, seniority and rate periods','catalog','tablelink')}</li><li>${ic('calendar')}${link('Working calendars and absences','calendar','tablelink')}</li><li>${ic('settings')}${link('Scenario overrides','assumptions','tablelink')}</li></ul>`)}${panel('Before you save',`<ul class="checklist"><li>${ic('check')} Rates have a currency and unit</li><li>${ic('check')} Percentage costs name their base</li><li>${ic('check')} Date ranges do not overlap</li><li>${ic('lock')} Requires organization administration access</li></ul>`)}</div></div>`}
window.addEventListener('hashchange',()=>{document.getElementById('dialog').close();ui.scenario='Base case';render();window.scrollTo(0,0)});
render();
